        annotated_real_rollout_count,
        NATIVE_PROGRESS_ACCEPTANCE_CASE_IDS.len(),
        "Packet R5-7 progress corpus must keep the committed shape of exactly {} annotated real-rollout cases",
        NATIVE_PROGRESS_ACCEPTANCE_CASE_IDS.len()
