use std::fs;

use agent_drift_analyzer::{analyze_bundle, AnalyzeRequest, DriftClass, DriftState};
use camino::{Utf8Path, Utf8PathBuf};
use serde::Deserialize;
use tempfile::TempDir;

const SEMANTIC_GOAL_DRIFT_ACCEPTANCE_ROOT: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/semantic_goal_drift_acceptance"
);

const SEMANTIC_GOAL_DRIFT_ACCEPTANCE_CASE_IDS: [&str; 1] =
    ["synthetic-kickoff-anchor-unauthorized-pivot"];

#[derive(Debug, Clone, Deserialize, PartialEq, Eq)]
struct AcceptanceExpectedScore {
    state: DriftState,
    flagged: bool,
    raw_score: u8,
}

#[derive(Debug, Clone, Deserialize, PartialEq, Eq)]
struct SemanticGoalDriftAcceptanceExpected {
    case_id: String,
    source_artifact: String,
    notes: String,
    session_id: String,
    final_semantic_goal_drift: AcceptanceExpectedScore,
    required_reason_prefixes: Vec<String>,
}

struct SemanticGoalDriftAcceptanceFixture {
    _temp_dir: TempDir,
    input_dir: Utf8PathBuf,
    output_dir: Utf8PathBuf,
    expected: SemanticGoalDriftAcceptanceExpected,
}

impl SemanticGoalDriftAcceptanceFixture {
    fn load(case_id: &str) -> Self {
        let input_dir = semantic_goal_drift_acceptance_fixture_dir(case_id);
        let expected = read_json(input_dir.join("expected.json").as_ref());
        let temp_dir = TempDir::new().expect("temp dir");
        let root = Utf8Path::from_path(temp_dir.path()).expect("utf8 temp dir");
        let output_dir = root.join("output");
        fs::create_dir_all(&output_dir).expect("create output dir");

        Self {
            _temp_dir: temp_dir,
            input_dir,
            output_dir,
            expected,
        }
    }

    fn request(&self) -> AnalyzeRequest {
        AnalyzeRequest {
            input_dir: self.input_dir.clone(),
            output_dir: self.output_dir.clone(),
        }
    }
}

#[test]
fn semantic_goal_drift_acceptance_fixture_root_stays_bounded() {
    let fixture_root = std::path::Path::new(SEMANTIC_GOAL_DRIFT_ACCEPTANCE_ROOT);
    let mut expected_root_entries = SEMANTIC_GOAL_DRIFT_ACCEPTANCE_CASE_IDS
        .iter()
        .map(|case_id| (*case_id).to_owned())
        .collect::<Vec<_>>();
    expected_root_entries.push("README.md".to_owned());
    expected_root_entries.sort();

    assert_eq!(
        sorted_entry_names(fixture_root),
        expected_root_entries,
        "R6-2.4 semantic-goal-drift acceptance corpus must stay bounded to README.md plus the approved case directories"
    );

    let expected_case_entries = [
        "dedupe-audit.jsonl",
        "expected.json",
        "manifest.json",
        "rows.archival.jsonl",
        "rows.compact.jsonl",
    ]
    .into_iter()
    .map(str::to_owned)
    .collect::<Vec<_>>();

    for case_id in SEMANTIC_GOAL_DRIFT_ACCEPTANCE_CASE_IDS {
        let fixture_dir = fixture_root.join(case_id);
        assert_eq!(
            sorted_entry_names(&fixture_dir),
            expected_case_entries,
            "semantic-goal-drift acceptance case {case_id} must keep the committed bundle contract files only"
        );
    }
}

#[test]
fn semantic_goal_drift_acceptance_flags_kickoff_anchor_pivot_end_to_end() {
    for case_id in SEMANTIC_GOAL_DRIFT_ACCEPTANCE_CASE_IDS {
        let fixture = SemanticGoalDriftAcceptanceFixture::load(case_id);
        let result = analyze_bundle(&fixture.request()).expect("analyze semantic-goal-drift case");
        let checkpoint = result
            .sessions
            .iter()
            .find(|session| session.session_id == fixture.expected.session_id)
            .and_then(|session| session.checkpoints.last())
            .expect("expected acceptance checkpoint");
        let score = checkpoint
            .drift_scores
            .iter()
            .find(|score| score.class == DriftClass::SemanticGoalDrift)
            .expect("expected semantic_goal_drift score");

        assert_eq!(score.state, fixture.expected.final_semantic_goal_drift.state);
        assert_eq!(
            score.flagged,
            fixture.expected.final_semantic_goal_drift.flagged
        );
        assert_eq!(
            score.raw_score,
            fixture.expected.final_semantic_goal_drift.raw_score
        );
        for prefix in &fixture.expected.required_reason_prefixes {
            assert!(
                score.evidence.iter().any(|item| item.reason.starts_with(prefix)),
                "expected semantic-goal-drift evidence prefix `{prefix}` in {case_id}"
            );
        }
    }
}

fn semantic_goal_drift_acceptance_fixture_dir(case_id: &str) -> Utf8PathBuf {
    let input_dir = Utf8PathBuf::from(SEMANTIC_GOAL_DRIFT_ACCEPTANCE_ROOT).join(case_id);
    assert!(
        input_dir.is_dir(),
        "missing semantic-goal-drift acceptance fixture {case_id}; tests must not fall back to target/ or ~/.codex"
    );
    input_dir
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Utf8Path) -> T {
    serde_json::from_str(&fs::read_to_string(path).expect("read json artifact"))
        .expect("parse json artifact")
}

fn sorted_entry_names(path: &std::path::Path) -> Vec<String> {
    let mut entries = fs::read_dir(path)
